SELECT debtorsmaster.debtorno, debtorsmaster.name, debtorsmaster.address1, debtorsmaster.address3, debtorsmaster.address4, debtorsmaster.address5, (select sum(discountedlinetotal * -1) as total from stocktrans where debtorno = debtorsmaster.debtorno) as totalspend, (select max(trandate) from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno) as lastseen, (select date_diff('day', max(trandate), current_date) from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno) as dayssince, (select transno from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno order by trandate desc limit 1 ) as lastinvoice FROM debtorsmaster WHERE 1=1 and debtorno in (select debtorno from custbranch where defaultlocation in (select loccode from locationusers where userid ='JACK')) AND debtorsmaster.debtorno not IN ( SELECT debtorno FROM stockmoves WHERE trandate >= current_date - INTERVAL 60 DAY AND trandate <= current_date GROUP BY debtorno ) and debtorno in (select debtorno from stockmoves where trandate >= current_date - INTERVAL 365 DAY) LIMIT 100 OFFSET 0 
